pub fn to_toggle_case(str1: &Vec<char>) -> Vec<char> {
    str1.iter()
        .map(|&c| match c {
            'a'..='z' => ((c as u8) - b'a' + b'A') as char, // ASCII lowercase -> uppercase
            'A'..='Z' => ((c as u8) - b'A' + b'a') as char, // ASCII uppercase -> lowercase
            _ => c,                                         // everything else unchanged
        })
        .collect()
}